//! `meshd service install | uninstall | start | stop | status` (spec §6.4): the daemon as an
//! OS service — systemd on Linux, the service control manager on Windows, launchd on macOS
//! (best-effort). Every command that changes the machine checks for root / Administrator
//! first and refuses with the spec's message (§7) before touching anything.
//!
//! The unit file and the plist are generated by pure functions ([`linux::unit_file`],
//! [`macos::plist`]) compiled everywhere, so they are golden-tested on every platform.

use std::fmt;
use std::io;
use std::path::Path;

use crate::ConfigError;

pub mod linux;
pub mod macos;

#[cfg(windows)]
pub mod eventlog;
#[cfg(windows)]
pub mod windows;

/// The service's name in systemd, the SCM and (as the account and group) on Linux.
pub const SERVICE_NAME: &str = "meshnode";

/// Whether the service is installed and running.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ServiceStatus {
    NotInstalled,
    Stopped,
    Starting,
    Running,
    Stopping,
}

impl fmt::Display for ServiceStatus {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            ServiceStatus::NotInstalled => "not installed",
            ServiceStatus::Stopped => "installed, stopped",
            ServiceStatus::Starting => "installed, starting",
            ServiceStatus::Running => "installed, running",
            ServiceStatus::Stopping => "installed, stopping",
        })
    }
}

#[derive(Debug, thiserror::Error)]
pub enum ServiceError {
    /// Not root / not elevated (spec §7).
    #[error("service {action} requires {PRIVILEGED}")]
    NeedsPrivileges { action: &'static str },
    #[error("the {SERVICE_NAME} service is not installed")]
    NotInstalled,
    #[error(
        "the {SERVICE_NAME} service is already installed (run `meshd service uninstall` first)"
    )]
    AlreadyInstalled,
    #[error("OS services are not supported on this platform")]
    Unsupported,
    #[error("{what}: {source}")]
    Io { what: String, source: io::Error },
    /// A system call or helper command failed; the message says which and why.
    #[error("{0}")]
    Failed(String),
    #[error(transparent)]
    Config(#[from] ConfigError),
}

/// Who may change services, as §7's messages name them.
#[cfg(windows)]
const PRIVILEGED: &str = "Administrator";
#[cfg(not(windows))]
const PRIVILEGED: &str = "root";

/// Wraps an I/O error with what was being done.
pub(crate) fn io_err(what: impl Into<String>) -> impl FnOnce(io::Error) -> ServiceError {
    let what = what.into();
    move |source| ServiceError::Io { what, source }
}

/// True when this process runs as root (Unix) or with an elevated token (Windows).
pub fn is_elevated() -> bool {
    #[cfg(unix)]
    {
        // SAFETY: geteuid has no preconditions and cannot fail.
        unsafe { libc::geteuid() == 0 }
    }
    #[cfg(windows)]
    {
        windows::token_is_elevated()
    }
    #[cfg(not(any(unix, windows)))]
    {
        false
    }
}

/// The privilege check every changing command starts with.
fn require_privileges(action: &'static str) -> Result<(), ServiceError> {
    if !cfg!(any(windows, target_os = "linux", target_os = "macos")) {
        return Err(ServiceError::Unsupported);
    }
    if is_elevated() {
        Ok(())
    } else {
        Err(ServiceError::NeedsPrivileges { action })
    }
}

#[cfg(target_os = "linux")]
use linux as platform;
#[cfg(target_os = "macos")]
use macos as platform;
#[cfg(windows)]
use windows as platform;

/// Elsewhere (Android, other Unixes) there is no service support.
#[cfg(not(any(windows, target_os = "linux", target_os = "macos")))]
mod platform {
    use std::path::Path;

    use super::{ServiceError, ServiceStatus};

    pub fn install(_data: &Path) -> Result<(), ServiceError> {
        Err(ServiceError::Unsupported)
    }
    pub fn uninstall() -> Result<(), ServiceError> {
        Err(ServiceError::Unsupported)
    }
    pub fn start() -> Result<(), ServiceError> {
        Err(ServiceError::Unsupported)
    }
    pub fn stop() -> Result<(), ServiceError> {
        Err(ServiceError::Unsupported)
    }
    pub fn status() -> Result<ServiceStatus, ServiceError> {
        Err(ServiceError::Unsupported)
    }
}

/// Installs the service for the data directory `data` and starts it.
pub fn install(data: &Path) -> Result<(), ServiceError> {
    require_privileges("install")?;
    // The service is started elsewhere; a relative directory would mean nothing there.
    let data =
        std::path::absolute(data).map_err(io_err(format!("resolving {}", data.display())))?;
    platform::install(&data)
}

/// Stops and removes the service; with `purge_data` also deletes the data directory
/// `data`, which is otherwise kept.
pub fn uninstall(data: &Path, purge_data: bool) -> Result<(), ServiceError> {
    require_privileges("uninstall")?;
    platform::uninstall()?;
    if purge_data {
        match std::fs::remove_dir_all(data) {
            Err(e) if e.kind() != io::ErrorKind::NotFound => {
                return Err(io_err(format!("removing {}", data.display()))(e));
            }
            _ => {}
        }
    }
    Ok(())
}

/// Starts the installed service.
pub fn start() -> Result<(), ServiceError> {
    require_privileges("start")?;
    platform::start()
}

/// Stops the installed service and waits until it has stopped.
pub fn stop() -> Result<(), ServiceError> {
    require_privileges("stop")?;
    platform::stop()
}

/// Whether the service is installed, and its state. Needs no privileges.
pub fn status() -> Result<ServiceStatus, ServiceError> {
    platform::status()
}

/// Helpers shared by the systemd and launchd installers.
#[cfg(any(target_os = "linux", target_os = "macos"))]
mod unix {
    use std::os::unix::fs::PermissionsExt;
    use std::path::Path;
    use std::process::{Command, Output};

    use super::{ServiceError, io_err};

    /// Where both installers put the binary.
    pub const INSTALLED_BINARY: &str = "/usr/local/bin/meshd";

    /// Runs a helper command; a non-zero exit is an error carrying its stderr.
    pub fn run(program: &str, args: &[&str]) -> Result<(), ServiceError> {
        let out = output(program, args)?;
        if out.status.success() {
            return Ok(());
        }
        Err(ServiceError::Failed(format!(
            "`{program} {}` failed ({}): {}",
            args.join(" "),
            out.status,
            String::from_utf8_lossy(&out.stderr).trim()
        )))
    }

    /// Runs a helper command and returns what it did, whatever its exit status.
    pub fn output(program: &str, args: &[&str]) -> Result<Output, ServiceError> {
        Command::new(program)
            .args(args)
            .output()
            .map_err(io_err(format!("running {program}")))
    }

    /// Copies the running executable to [`INSTALLED_BINARY`] (mode 0755), unless it is
    /// that file already. Writes a temporary file and renames it, so a running copy is
    /// replaced rather than overwritten.
    pub fn install_binary() -> Result<(), ServiceError> {
        let target = Path::new(INSTALLED_BINARY);
        let source = std::env::current_exe().map_err(io_err("finding the meshd executable"))?;
        if let (Ok(a), Ok(b)) = (source.canonicalize(), target.canonicalize())
            && a == b
        {
            return Ok(());
        }
        let dir = target.parent().expect("an absolute path");
        std::fs::create_dir_all(dir).map_err(io_err(format!("creating {}", dir.display())))?;
        let tmp = dir.join(".meshd.install");
        std::fs::copy(&source, &tmp).map_err(io_err(format!(
            "copying {} to {}",
            source.display(),
            tmp.display()
        )))?;
        std::fs::set_permissions(&tmp, std::fs::Permissions::from_mode(0o755))
            .map_err(io_err(format!("setting the mode of {}", tmp.display())))?;
        std::fs::rename(&tmp, target).map_err(io_err(format!("installing {}", target.display())))
    }

    /// Writes a root-owned configuration file with mode 0644.
    pub fn write_file(path: &Path, text: &str) -> Result<(), ServiceError> {
        std::fs::write(path, text).map_err(io_err(format!("writing {}", path.display())))?;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o644))
            .map_err(io_err(format!("setting the mode of {}", path.display())))
    }

    /// Removes a file; a missing one is fine.
    pub fn remove_file(path: &Path) -> Result<(), ServiceError> {
        match std::fs::remove_file(path) {
            Err(e) if e.kind() != std::io::ErrorKind::NotFound => {
                Err(io_err(format!("removing {}", path.display()))(e))
            }
            _ => Ok(()),
        }
    }
}
